                                    end
                                    if AnyLive then
                                        break
                                    end
                                end
                            end
                            if AnyLive then
                                self.OrphanPuzzleAt = os.clock()
                            else
                                self.OrphanPuzzleAt = nil
                                for i,Orphan in PlayerGui:GetChildren() do
                                    if Orphan.Name == "PuzzleUI" then
                                        Orphan:Destroy()
                                    end
                                end
                            end
