        },
        -- ================= ADDON: Server Position Spoof (lag compensation) =================
        -- Asal: script ForsakenSpoof (hook CharacterReplication.Serialize). Di sini ditulis ulang jadi
        -- feature native: tanpa getgenv, hook dipasang/dilepas lewat ScriptFunction, dan nilai
        -- MaxOffset / PingDivisor dibaca live dari setting di bawah (SpoofMaxOffset / SpoofPingDivisor).
        -- Cara kerja: posisi server (silinder biru kalau "Show collision hitboxes" nyala) didorong ke
        -- arah MoveDirection sebesar min(max(speed, WalkSpeed) * ping(ms) / divisor, maxOffset),
        -- supaya hitbox tidak tertinggal di belakang saat ping tinggi. Tanpa setting itu, tidak ada
        -- perbedaan visual selain tempat hitbox spawn.
        ["ServerPositionSpoof"] = {
            ["DisplayDescription"] = "Pushes YOUR OWN server position ahead of your movement (based on ping) so your hits land where you aim. It does NOT move the enemy hitbox. For laggy players: without this, your hitbox trails behind you. At low ping the offset is tiny by design (e.g. 40 ms ping = ~0.5 studs) - lower Ping Divisor to feel it. No visual change unless 'Show collision hitboxes' is on (blue cylinder = server position). Check console (F9) for offset logs.",
            ["DisplayTitle"] = "Server Position Spoof",
            ["LayoutOrder"] = 6,
            ["Savable"] = true,
            ["InstanceType"] = "BoolValue",
            ["DefaultInstanceValue"] = false,
            ["ScriptFunction"] = function(self, Value)
                if Value then
                    self.SpoofEnabled = true
                    if self.SpoofHook or self.SpoofInstalling then return end
                    self.SpoofInstalling = true
                    task.spawn(function()
                        local ok, Mod = pcall(function()
                            local Systems = ReplicatedStorage:WaitForChild("Systems", 5)
                            local PlayerSys = Systems and Systems:WaitForChild("Player", 5)
                            local GameSys = PlayerSys and PlayerSys:WaitForChild("Game", 5)
                            local CharRep = GameSys and GameSys:WaitForChild("CharacterReplication", 5)
                            return CharRep and require(CharRep) or nil
                        end)
                        self.SpoofInstalling = false
                        if not self.SpoofEnabled then return end
                        if not ok or not Mod or type(Mod.Serialize) ~= "function" then
                            self.SpoofEnabled = false
                            if self.Instance then self.Instance.Value = false end
                            StarterGui:SetCore("SendNotification", {
                                Title = "Server Position Spoof", Text = "CharacterReplication module not found, feature disabled.",
                                Icon = "rbxasset://textures/DevConsole/Warning.png", Duration = 4.5
                            })
                            return
                        end
                        local Original = Mod.Serialize
                        local Feature = self
                        local function SpoofedSerialize(...)
                            local Args = { ... }
                            local HasSelf = false
                            local P1, P2
                            if typeof(Args[1]) == "Vector3" then
                                P1, P2 = Args[1], Args[2]
                            elseif typeof(Args[2]) == "Vector3" then
                                HasSelf = true
                                P1, P2 = Args[2], Args[3]
                            else
                                return Original(...)
                            end
                            local function Passthrough()
                                if HasSelf then return Original(Args[1], P1, P2) else return Original(P1, P2) end
                            end
                            if not Feature.SpoofEnabled then return Passthrough() end
                            local Char = LocalPlayer.Character
                            local PrimaryPart = Char and Char.PrimaryPart
                            local Humanoid = Char and Char:FindFirstChildOfClass("Humanoid")
                            if not (PrimaryPart and Humanoid and typeof(P1) == "CFrame" and (P1.Position - PrimaryPart.Position).Magnitude < 15) then
                                return Passthrough()
                            end
                            local MoveDirection = Humanoid.MoveDirection
                            if MoveDirection.Magnitude <= 0.1 then return Passthrough() end
                            local Magnitude = PrimaryPart.AssemblyLinearVelocity.Magnitude
                            local WalkSpeed = Humanoid.WalkSpeed
                            local Divisor = tonumber(GetValue("SpoofPingDivisor")) or 1400
                            if Divisor <= 0 then Divisor = 1400 end
                            local MaxOffset = tonumber(GetValue("SpoofMaxOffset")) or 4
                            local Offset = math.min(math.max(Magnitude, WalkSpeed) * (LocalPlayer:GetNetworkPing() * 1000) / Divisor, MaxOffset)
                            local Flat = Vector3.new(MoveDirection.X, 0, MoveDirection.Z)
                            if Flat.Magnitude <= 0 then return Passthrough() end
                            P1 = P1 + Flat.Unit * Offset
                            -- DEBUG (throttled): buktiin hook-nya jalan & offset-nya berapa. Cek di console (F9).
                            Feature.SpoofLogTick = (Feature.SpoofLogTick or 0) + 1
                            if Feature.SpoofLogTick % 120 == 0 then
                                print(string.format("[ServerPositionSpoof] offset=%.2f studs | ping=%.0f ms | speed=%.1f", Offset, LocalPlayer:GetNetworkPing() * 1000, math.max(Magnitude, WalkSpeed)))
                            end
                            return Passthrough()
                        end
                        Mod.Serialize = SpoofedSerialize
                        self.SpoofHook = { Module = Mod, Original = Original }
                        print("[ServerPositionSpoof] hook installed on CharacterReplication.Serialize")
                    end)
                else
                    self.SpoofEnabled = false
                    if self.SpoofHook then
                        pcall(function() self.SpoofHook.Module.Serialize = self.SpoofHook.Original end)
                        self.SpoofHook = nil
                        print("[ServerPositionSpoof] hook removed, Serialize restored")
                    end
                end
            end,
        },
