                local PlayersFolder = workspace:FindFirstChild("Players")
                local Spectators = PlayersFolder and PlayersFolder:FindFirstChild("Spectating")
                if Spectators and Char.Parent == Spectators then return end
                local Humanoid = Char:FindFirstChildOfClass("Humanoid") or Char:WaitForChild("Humanoid", 10)
                if not Humanoid then return end
                self:StopInvis()
                local Anim = Instance.new("Animation")
                Anim.AnimationId = self:GetAnimId()
                local ok, Track = pcall(function() return Humanoid:LoadAnimation(Anim) end)
                if not ok or not Track then
                    Anim:Destroy()
                    ColoredPrint("Animation Invisibility: failed to load the summon animation.", "info", Color3.new(1, 0.25, 0))
                    if self.Instance then self.Instance.Value = false end
                    return
                end
                self.InvisAnim = Anim
                self.InvisTrack = Track
                Track:Play()
                Track:AdjustSpeed(0)
                Track.TimePosition = 0
            end,
            ["StopInvis"] = function(self)
                if self.InvisTrack then
                    pcall(function() self.InvisTrack:Stop() end)
