local function Nexrift_GetTab(TabName)
    local Mapped = TabName
    if TabName == "EnviromentFunctions" or TabName == "Unofficial" or TabName == "Outdated" then Mapped = "Info" end
    if NexriftTabs[Mapped] then return NexriftTabs[Mapped], Mapped end
    local Info = Nexrift_TabInfo[Mapped]
    local Tab
    if Info then Tab = NexriftGroup:Tab({ Title = Info.Title, Icon = Info.Icon, Subtitle = Info.Subtitle })
    else Tab = NexriftGroup:Tab({ Title = Nexrift_CleanText(TabName), Icon = "settings", Subtitle = "Plugin" }) end
    NexriftTabs[Mapped] = Tab
    return Tab, Mapped
end
local function Nexrift_GetSubTab(TabName, SettingName)
    local Tab, Mapped = Nexrift_GetTab(TabName)
    local Route = Nexrift_Route[SettingName]
    local SubName = Route and Route.SubTab or nil
    if Mapped == "Info" then SubName = nil end
    if not SubName then return Tab, nil end
    local Key = Mapped .. "|" .. SubName
    if NexriftSubTabs[Key] then return NexriftSubTabs[Key], SubName end
    local Sub = Tab:SubTab({ Title = SubName })
    NexriftSubTabs[Key] = Sub
    return Sub, SubName
end
local function Nexrift_GetAccordion(TabName, SettingName)
    local Parent, SubName = Nexrift_GetSubTab(TabName, SettingName)
    local Route = Nexrift_Route[SettingName]
    local AccTitle, AccIcon, AccCol
    if Route then AccTitle = Route.Accordion; AccIcon = Route.Icon; AccCol = Route.Column
    elseif TabName == "EnviromentFunctions" then AccTitle = "About"; AccIcon = "info"; AccCol = 1
    elseif TabName == "Unofficial" or TabName == "Outdated" then AccTitle = "Status"; AccIcon = "info"; AccCol = 1
    else AccTitle = "Plugin Features"; AccIcon = "settings"; AccCol = 1 end
    local Key = (TabName or "?") .. "|" .. (SubName or "-") .. "|" .. AccTitle
    if NexriftAccordions[Key] then return NexriftAccordions[Key], Key end
    local Acc = Parent:Accordion({ Title = AccTitle, Icon = AccIcon, Column = AccCol, Default = true })
    NexriftAccordions[Key] = Acc
    NexriftAccordionFeatures[Acc] = {}
    Acc:Button({ Title = "Reset " .. AccTitle .. " to Default", Desc = "Reset all features in this accordion",
        Callback = function()
            for _, Entry in ipairs(NexriftAccordionFeatures[Acc] or {}) do
                pcall(function() if Entry.Instance and Entry.Default ~= nil then Entry.Instance.Value = Entry.Default end end)
            end
        end })
    return Acc, Key
end
local Nexrift_InfoIntroDone = false
local function Nexrift_EnsureInfoIntro()
    if Nexrift_InfoIntroDone then return end
    Nexrift_InfoIntroDone = true
    local Tab = Nexrift_GetTab("Info")
    local Acc = Tab:Accordion({ Title = "About", Icon = "info", Column = 1, Default = true })
    Acc:Paragraph({ Title = "Forsaken Plus", Desc = "Script Made by Naiko Scripts | Version " .. tostring(Version) .. ". Logic 100% sama seperti script asli, hanya UI-nya yang dipindah ke Nexrift. Toggle dengan RightControl." })
    Acc:Button({ Title = "Copy Discord / Credits", Desc = "Credits: Naiko Scripts",
        Callback = function() pcall(function() if setclipboard then setclipboard("Forsaken Plus by Naiko Scripts | Version " .. tostring(Version)) end end) end })
end

