    		Metaverse.Menu.Parent = MainUI
    		for i, v in Metaverse.Menu:QueryDescendants("ScrollingFrame") do
    			v:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
    				v.ScrollBarThickness = v.AbsoluteSize.X / 44
    			end)
