    			if v2:IsA("Frame") then
    				MenuData.SidebarButtons[v2.Name] = FallbackButton.new(v2, v.Name)
    				local Waiting = MenuData.PendingSidebarMenus[v2.Name]
    				if Waiting then
    					LoadFallbackButton(v2.Name, Waiting)
    				end
    			end
    		end
    	end
    end
